checks.ref:
command:change=$(find openspec/changes -mindepth 1 -maxdepth 1 -type d ! -name archive)
[ "$(printf '%s\n' "$change" | grep -c .)" = "1" ] || { echo "expected exactly one active change under openspec/changes/, found: $change"; exit 1; }
review="$change/review-specs.md"
[ -f "$review" ] || { echo "$review is missing - write the review report there, see stages/review-specs/instructions.md"; exit 1; }
for section in '## Summary' '## Freshness' '## Coverage' '## Consistency' '## Findings' '## Verdict'; do
  grep -q "^$section" "$review" || { echo "$review has no '$section' section"; exit 1; }
done
bad=$(grep -n '^### ' "$review" | grep -vE '^[0-9]+:### R[0-9]+ — (CRITICAL|WARNING|SUGGESTION) — .+' || true)
[ -z "$bad" ] || { echo "$bad"; echo "level-3 headings are findings only and read '### R<n> — CRITICAL|WARNING|SUGGESTION — <title>'"; exit 1; }
duplicates=$(grep -oE '^### R[0-9]+ ' "$review" | sort | uniq -d)
[ -z "$duplicates" ] || { echo "$duplicates"; echo "finding ids must be unique"; exit 1; }
findings=$(grep -cE '^### R[0-9]+ — ' "$review" || true)
for field in Location Rule Problem Impact Fix 'Fix risk' Status; do
  count=$(grep -cE "^- $field: " "$review" || true)
  [ "$count" = "$findings" ] || { echo "$review has $findings findings but $count '- $field:' lines - every finding carries every field exactly once"; exit 1; }
done
open=$(grep -cE '^- Status: open$' "$review" || true)
[ "$open" = "$findings" ] || { echo "every finding must stay at '- Status: open' - only the fix-specs stage sets a status"; exit 1; }
